for each student X:
    for each student Y after X:
        compare X and Y
    # The inner loop finishes before the next X.

Group the bills by Customer
for each customer bin B:
    if number of bills in B < 2:
        report "Too little evidence"
    else:
        FirstShop = the shop on the first bill
        SameShop = true
        for each bill X in B:
            if X.Store != FirstShop:
                SameShop = false
        if SameShop:
            report "Loyal in these observations"
        else:
            report "Uses multiple shops"

for each total band B:
    M = students in B with Mathematics > Physics
    P = students in B with Physics > Mathematics
    for each student X in M:
        for each student Y in P:
            if X.Mathematics > Y.Mathematics AND Y.Physics > X.Physics:
                report a candidate study pair

LastName = empty
for each word card X in paragraph order:
    if X is a recognized person name:
        LastName = X.Word
    if X is a relevant personal pronoun:
        if LastName is empty:
            report "Unresolved"
        else:
            report LastName as a candidate, not guaranteed meaning

# Count students, not qualifying subject marks
Count = 0
for each score card X:
    if X.Mathematics > 90 OR X.Physics > 90:
        Count = Count + 1

# Different result: this counts successful subject tests
Count = 0
for each score card X:
    if X.Mathematics > 90:
        Count = Count + 1
    if X.Physics > 90:
        Count = Count + 1

Ncount = 0
Vcount = 0
for each word card X:
    if X.PartOfSpeech == "Noun":
        Ncount = Ncount + 1
    if X.PartOfSpeech == "Verb":
        Vcount = Vcount + 1
# Ncount = 21, Vcount = 7

Procedure CountVowelsAndConsonants(X):
    Letters = alphabetic letters of X.Word
    i = 1
    Vcount = 0
    Ccount = 0
    while i <= number of Letters:
        if lowercase(Letters[i]) is one of a, e, i, o, u:
            Vcount = Vcount + 1
        else:
            Ccount = Ccount + 1
        i = i + 1
    return (Vcount, Ccount)
End Procedure
